contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 newAmount, uint256 seedAmount) public {
        c.AdjustDifficulty(seedAmount); if (__ESBMC_reverted()) return;
        uint256 originalDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.AdjustDifficulty(newAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterDifficulty = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        assert(!reverted && afterDifficulty == newAmount && afterDifficulty != originalDifficulty || newAmount == originalDifficulty);
    }

    receive() external payable {}
}

