pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newAmount, uint256 seedAmount) internal {
        try c.AdjustDifficulty(seedAmount) {} catch { return; }
        uint256 originalDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { originalDifficulty = __r; } catch { return; }
        bool reverted;
        try c.AdjustDifficulty(newAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterDifficulty;
        try c.currentDifficulty() returns (uint256 __r) { afterDifficulty = __r; } catch { return; }
        assertTrue(!reverted && afterDifficulty == newAmount && afterDifficulty != originalDifficulty || newAmount == originalDifficulty);
    }

    function testFuzz_run(uint256 newAmount, uint256 seedAmount) public {
        _run(newAmount, seedAmount);
    }

    receive() external payable {}
}
